package com.chatsystem.user.controller.social;
import com.chatsystem.shared.model.UserAccount;import com.chatsystem.shared.service.*;import com.chatsystem.user.navigation.*;import com.chatsystem.user.ui.cell.FriendCell;import javafx.collections.transformation.*;import javafx.fxml.FXML;import javafx.scene.control.*;import javafx.scene.layout.HBox;import java.util.*;
public final class FriendsController{
 private final SocialService social;private final ChatService chat;private final UserNavigator nav;@FXML private TextField friendSearchField;@FXML private ListView<UserAccount> friendList;@FXML private Label socialFeedbackLabel;@FXML private HBox socialConfirmationBar;@FXML private ChoiceBox<String> friendSortChoice;private Runnable pending;
 public FriendsController(SocialService s,ChatService c,UserNavigator n){social=s;chat=c;nav=n;}
 @FXML private void initialize(){var sorted=new SortedList<>(social.getFriends(),Comparator.comparing(UserAccount::getDisplayName));var filtered=new FilteredList<>(sorted);friendList.setItems(filtered);friendList.setCellFactory(x->new FriendCell(this::message,this::requestBlock));friendSortChoice.getItems().setAll("Online first","Name");friendSortChoice.getSelectionModel().selectFirst();friendSortChoice.getSelectionModel().selectedItemProperty().addListener((o,a,t)->sorted.setComparator("Name".equals(t)?Comparator.comparing(UserAccount::getDisplayName):Comparator.comparing((UserAccount u)->u.getStatus()!=com.chatsystem.shared.model.status.UserStatus.ACTIVE).thenComparing(UserAccount::getDisplayName)));friendSearchField.textProperty().addListener((o,a,t)->filtered.setPredicate(u->u.getDisplayName().toLowerCase(Locale.ROOT).contains(t.toLowerCase(Locale.ROOT))||u.getUsername().toLowerCase(Locale.ROOT).contains(t.toLowerCase(Locale.ROOT))));}
 @FXML private void message(){message(selected());}private void message(UserAccount u){if(u==null)return;var r=chat.startConversation(u.getId());if(r.isSuccess())nav.navigate(ViewRequest.conversation(UserRoute.CHAT_PRIVATE,r.value().orElseThrow().getId()));else show(r.errors().get(0).message());}
 @FXML private void block(){requestBlock(selected());}private void requestBlock(UserAccount u){if(u==null){show("Choose a friend to block");return;}pending=()->{var r=social.blockUser(u.getId());show(r.isSuccess()?"User blocked":r.errors().get(0).message());};socialConfirmationBar.setManaged(true);socialConfirmationBar.setVisible(true);}
 @FXML private void confirmSocial(){if(pending!=null)pending.run();cancelSocial();}@FXML private void cancelSocial(){pending=null;socialConfirmationBar.setManaged(false);socialConfirmationBar.setVisible(false);}
 @FXML private void openAdd(){nav.showDialog("/fxml/dialogs/add-friend.fxml","Add friend");}
 @FXML private void requests(){nav.navigate(ViewRequest.of(UserRoute.FRIEND_REQUESTS));}@FXML private void blocked(){nav.navigate(ViewRequest.of(UserRoute.BLOCKED_USERS));}
 private UserAccount selected(){return friendList.getSelectionModel().getSelectedItem();}private void show(String s){socialFeedbackLabel.setText(s);}
}
